// @ts-check
import { defineConfig, fontProviders } from 'astro/config';
import starlight from '@astrojs/starlight';
import { readFileSync } from 'node:fs';

// The merged text catalogue, generated by `pnpm catalog` (scripts/catalog/build.mjs).
const catalog = JSON.parse(readFileSync(new URL('./src/data/catalog.json', import.meta.url), 'utf8'));

const SITE = 'https://meobtis.github.io';
const DESCRIPTION =
	'An index of Buddhist texts in Sanskrit from GRETIL, the Digital Sanskrit Buddhist Canon and SARIT, ' +
	'converted to Markdown and readable online in IAST and Devanāgarī.';
const OG_IMAGE = { url: `${SITE}/meobtis-og.jpeg`, alt: 'Sanskrit manuscript of the Heart Sūtra in Siddhaṃ script' };
// The logo and share image: a public-domain photograph from Wikimedia Commons (see About › Image credit).
const IMAGE_CREDIT = {
	'@type': 'ImageObject',
	contentUrl: OG_IMAGE.url,
	caption: 'Sanskrit manuscript of the Prajñāpāramitāhṛdaya (Heart Sūtra) in Siddhaṃ script',
	creditText: 'Bibliothèque nationale de France, via Wikimedia Commons',
	copyrightNotice: 'Public domain',
	license: 'https://creativecommons.org/publicdomain/mark/1.0/',
	acquireLicensePage: 'https://commons.wikimedia.org/wiki/File:Prajnyaapaaramitaa_Hridaya_Pel.sogd.jpg',
	isBasedOn: 'https://gallica.bnf.fr/ark:/12148/btv1b8305799x',
};

// Site-wide structured data (schema.org): the website and the organisation behind it.
const jsonLd = {
	'@context': 'https://schema.org',
	'@graph': [
		{
			'@type': 'WebSite',
			'@id': `${SITE}/#website`,
			url: `${SITE}/`,
			name: 'MEOBTIS',
			alternateName: 'Markdown Editions Of Buddhist Texts In Sanskrit',
			description: DESCRIPTION,
			inLanguage: 'en',
			image: IMAGE_CREDIT,
			publisher: { '@id': `${SITE}/#organization` },
		},
		{
			'@type': 'Organization',
			'@id': `${SITE}/#organization`,
			name: 'MEOBTIS',
			url: `${SITE}/`,
			logo: `${SITE}/meobtis-square.jpeg`,
			sameAs: ['https://github.com/meobtis'],
		},
	],
};

// https://astro.build/config
export default defineConfig({
	// User/organisation GitHub Pages site, so no `base` is needed.
	site: SITE,
	// Astro Fonts API: fonts are downloaded at build time and self-hosted from /_astro/fonts.
	// The <Font /> tags are rendered in src/components/Head.astro.
	fonts: [
		{
			provider: fontProviders.fontsource(),
			name: 'Noto Sans',
			cssVariable: '--font-noto-sans',
			weights: [400, 600],
			styles: ['normal', 'italic'],
			// latin-ext covers IAST diacritics (ā ī ū ṛ ṃ ḥ ś ṣ ṇ ṭ ḍ …).
			subsets: ['latin', 'latin-ext'],
			fallbacks: ['sans-serif'],
		},
		{
			provider: fontProviders.fontsource(),
			name: 'Noto Sans Devanagari',
			cssVariable: '--font-noto-sans-devanagari',
			weights: [400, 600],
			styles: ['normal'],
			subsets: ['devanagari'],
			// No fallbacks: this family is listed *first* in --sl-font and its unicode-range
			// covers only Devanāgarī, so Latin text falls through to Noto Sans (see rosely.css).
			fallbacks: [],
			optimizedFallbacks: false,
		},
		{
			provider: fontProviders.fontsource(),
			name: 'Noto Sans Mono',
			cssVariable: '--font-noto-sans-mono',
			weights: [400, 600],
			styles: ['normal'],
			subsets: ['latin', 'latin-ext'],
			fallbacks: ['monospace'],
		},
	],
	integrations: [
		starlight({
			title: 'MEOBTIS',
			description: DESCRIPTION,
			logo: { src: './public/meobtis-square.jpeg' },
			favicon: '/icon-32.png',
			// SEO: Starlight already emits <title>, the meta description, canonical URL,
			// og:title/description/url/site_name, twitter:card and the sitemap link.
			// These add the share image, icons, theme colours and structured data.
			head: [
				{ tag: 'link', attrs: { rel: 'apple-touch-icon', href: '/apple-touch-icon.png' } },
				{ tag: 'link', attrs: { rel: 'manifest', href: '/site.webmanifest' } },
				{ tag: 'meta', attrs: { name: 'theme-color', content: '#ffffff', media: '(prefers-color-scheme: light)' } },
				{ tag: 'meta', attrs: { name: 'theme-color', content: '#1c1425', media: '(prefers-color-scheme: dark)' } },
				{ tag: 'meta', attrs: { property: 'og:image', content: OG_IMAGE.url } },
				{ tag: 'meta', attrs: { property: 'og:image:type', content: 'image/jpeg' } },
				{ tag: 'meta', attrs: { property: 'og:image:width', content: '1200' } },
				{ tag: 'meta', attrs: { property: 'og:image:height', content: '630' } },
				{ tag: 'meta', attrs: { property: 'og:image:alt', content: OG_IMAGE.alt } },
				{ tag: 'meta', attrs: { name: 'twitter:image', content: OG_IMAGE.url } },
				{ tag: 'meta', attrs: { name: 'twitter:image:alt', content: OG_IMAGE.alt } },
				{ tag: 'script', attrs: { type: 'application/ld+json' }, content: JSON.stringify(jsonLd) },
			],
			social: [
				{ icon: 'github', label: 'GitHub', href: 'https://github.com/meobtis/meobtis.github.io' },
			],
			editLink: {
				baseUrl: 'https://github.com/meobtis/meobtis.github.io/edit/main/',
			},
			lastUpdated: true,
			components: {
				// Adds Astro's <Font /> tags to every page's <head>.
				Head: './src/components/Head.astro',
				// Adds a credit line for the text sources to every page.
				Footer: './src/components/Footer.astro',
			},
			// Rosely palette (same approach as rosely.hellotham.com).
			customCss: ['./src/styles/rosely.css'],
			sidebar: [
				{
					label: 'About',
					items: [
						{ label: 'About MEOBTIS', slug: 'about' },
						{ label: 'Sources', slug: 'about/sources' },
						{ label: 'Other collections', slug: 'about/collections' },
					],
				},
				{
					label: 'Texts',
					items: [
						{ label: 'Overview', link: '/texts/' },
						{ label: 'Reading path', link: '/path/' },
						{ label: 'All texts A–Z', link: '/texts/all/', badge: String(catalog.works.length) },
						// One group per section of the catalogue, one link per category (see scripts/catalog).
						...catalog.groups
							.filter((g) => g.count > 0)
							.map((g) => ({
								label: g.label,
								collapsed: true,
								items: g.categories
									.filter((c) => c.count > 0)
									.map((c) => ({
										label: c.label,
										link: `/texts/${g.id}/${c.id}/`,
										badge: String(c.count),
									})),
							})),
					],
				},
			],
		}),
	],
});
